/**
 * Authenticate a user by CNIC and password
 */
export const authenticateUser = (cnic, password) => {
  const user = users.find(
    (u) => u.cnic === cnic && u.password === password
  );
  if (!user) return null;
  // Return user without password
  const { password: _, ...safeUser } = user;
  return safeUser;
};

/**
 * Find a user by CNIC
 */
export const findUserByCnic = (cnic) => {
  const user = users.find((u) => u.cnic === cnic);
  if (!user) return null;
  const { password: _, ...safeUser } = user;
  return safeUser;
};

/**
 * Get all users by role
 */
export const getUsersByRole = (role) => {
  return users
    .filter((u) => u.role === role)
    .map(({ password: _, ...u }) => u);
};

/**
 * Create a new user (used by Admin or Guardian sign-up)
 */
export const createUser = (userData) => {
  // Check if CNIC already exists
  if (users.find((u) => u.cnic === userData.cnic)) {
    return { error: 'An account with this CNIC already exists.' };
  }

  const newUser = {
    id: String(Date.now()),
    ...userData,
    isVerified: false,
    createdAt: new Date().toISOString(),
  };

  users.push(newUser);
  const { password: _, ...safeUser } = newUser;
  return { user: safeUser };
};

/**
 * Get all users (admin function)
 */
export const getAllUsers = () => {
  return users.map(({ password: _, ...u }) => u);
};
